import{_ as a,o as e,c as n,a0 as t}from"./chunks/framework.BGyYNsHo.js";const u=JSON.parse('{"title":"Uniones virtuales ([VIRTUAL_JUNCTIONS])","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/05-uniones-virtuales.md","filePath":"es/explanation/modificaciones-motor/05-uniones-virtuales.md"}'),p={name:"es/explanation/modificaciones-motor/05-uniones-virtuales.md"};function m(r,s,i,l,o,c){return e(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="uniones-virtuales-virtual-junctions" tabindex="-1">Uniones virtuales (<code>[VIRTUAL_JUNCTIONS]</code>) <a class="header-anchor" href="#uniones-virtuales-virtual-junctions" aria-label="Permalink to &quot;Uniones virtuales (`[VIRTUAL_JUNCTIONS]`)&quot;">​</a></h1><h2 id="motivacion" tabindex="-1">Motivación <a class="header-anchor" href="#motivacion" aria-label="Permalink to &quot;Motivación&quot;">​</a></h2><p>Un cambio de pendiente en un conducto debe dividirse en una cámara de unión. Pero una cámara de unión ordinaria introduce dos artefactos numéricos:</p><ol><li><strong>Almacenamiento artificial</strong>: su área superficial se pisa con el mínimo <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>A</mi><mrow><mi>min</mi></mrow></msub><mo>=</mo><mn>1</mn><mn>2</mn><mi mathvariant="normal">.</mi><mn>5</mn><mn>6</mn><mn>6</mn><mtext> </mtext><mrow><mi mathvariant="normal">f</mi><msup><mi mathvariant="normal">t</mi><mn mathvariant="normal">2</mn></msup></mrow></mrow><annotation encoding="application/x-tex">A_{\\min} = 12.566\\ \\mathrm{ft^2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.964108em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">A</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mop">min</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span><span class="mord mathrm">6</span><span class="mord mspace"> </span><span class="mord textstyle uncramped"><span class="mord mathrm" style="margin-right:0.07778em;">f</span><span class="mord"><span class="mord mathrm">t</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span>, lo que agrega un volumen de estancamiento que &quot;emborrona&quot; los transitorios;</li><li><strong>Ruptura de momentum</strong>: el nodo actúa como un pequeño volumen de estancamiento que interrumpe la transmisión de momentum entre los dos conductos.</li></ol><p>Una <strong>unión virtual</strong> (<code>[VIRTUAL_JUNCTIONS]</code>, sección con nombre y cota de batea; todo lo demás se deriva) elimina ambos artefactos para dos conductos colineales de sección idéntica que se encuentran en un quiebre de pendiente. Se declara un nodo sellado de almacenamiento idénticamente nulo. Las reglas de elegibilidad se verifican en la lectura: exactamente dos enlaces, ambos conductos; secciones transversales idénticas (forma, dimensiones, referencia de curva, número de barriles; la rugosidad de Manning puede diferir); ambos desfases en el nodo nulos con batea continua; sin aportes laterales de ningún tipo; y método de tránsito de onda dinámica. Cualquier violación es un error de entrada.</p><h2 id="tratamiento-de-continuidad" tabindex="-1">Tratamiento de continuidad <a class="header-anchor" href="#tratamiento-de-continuidad" aria-label="Permalink to &quot;Tratamiento de continuidad&quot;">​</a></h2><p>Una unión virtual es un nodo sellado de almacenamiento cero. Su carga se actualiza con la fórmula de superficie libre usando el área superficial natural de medio enlace aportada por sus dos conductos, <em>sin</em> el piso de área mínima (ese piso es precisamente el almacenamiento artificial que la funcionalidad elimina). Cuando el área natural se anula (par seco, o par en carga con ancho de ranura pequeño), la actualización cae a una forma pura de balance de caudales de la actualización en carga con <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>α</mi><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\alpha = 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.0037em;">α</span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span> y sin piso. En la convergencia, <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>∑</mo><mi>Q</mi><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sum Q = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.00001em;vertical-align:-0.25001em;"></span><span class="base textstyle uncramped"><span class="op-symbol small-op mop" style="top:-0.0000050000000000050004em;">∑</span><span class="mord mathit">Q</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> en el nodo. El nodo está sellado: su carga puede subir sobre la clave sin límite (como una cámara con tapa empernada), nunca se anega ni se encharca, y su volumen y rebalse son idénticamente cero.</p><h2 id="tratamiento-de-momentum" tabindex="-1">Tratamiento de momentum <a class="header-anchor" href="#tratamiento-de-momentum" aria-label="Permalink to &quot;Tratamiento de momentum&quot;">​</a></h2><p>Para un par de paso (un conducto entrando, otro saliendo), el conducto aguas abajo toma como estado aguas arriba los valores medios del conducto aguas arriba en su ponderación por Froude (mecanismo de <em>upwinding</em> a través del nodo), transportando el momentum advectado a través del nodo en lugar de reiniciarlo. Con <code>VIRTUAL_JUNCTION_MOMENTUM FULL</code> (por defecto <code>BASIC</code>) se agrega además una corrección convectiva al término de inercia de ambos conductos:</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">Δ</mi><msub><mi>Q</mi><mi>j</mi></msub><mo>=</mo><mi mathvariant="normal">Δ</mi><mi>t</mi><mspace width="0.16667em"></mspace><msub><mi>σ</mi><mi>j</mi></msub><mspace width="0.16667em"></mspace><mfrac><mrow><msub><mrow><mo fence="true">(</mo><msup><mover accent="true"><mi>U</mi><mo>¯</mo></mover><mrow><mn>2</mn></mrow></msup><mover accent="true"><mi>A</mi><mo>¯</mo></mover><mo fence="true">)</mo></mrow><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">b</mi></mrow></mrow></msub><mo>−</mo><msub><mrow><mo fence="true">(</mo><msup><mover accent="true"><mi>U</mi><mo>¯</mo></mover><mrow><mn>2</mn></mrow></msup><mover accent="true"><mi>A</mi><mo>¯</mo></mover><mo fence="true">)</mo></mrow><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">r</mi></mrow></mrow></msub></mrow><mrow><mi mathvariant="normal">Λ</mi></mrow></mfrac><mo separator="true">,</mo><mspace width="2em"></mspace><mi mathvariant="normal">Λ</mi><mo>=</mo><mfrac><mrow><msub><mi>L</mi><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">r</mi></mrow></mrow></msub><mo>+</mo><msub><mi>L</mi><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">b</mi></mrow></mrow></msub></mrow><mrow><mn>2</mn></mrow></mfrac><mo separator="true">,</mo></mrow><annotation encoding="application/x-tex">\\Delta Q_j = \\Delta t\\,\\sigma_j\\, \\frac{\\left(\\bar U^{2}\\bar A\\right)_{\\mathrm{ab}} - \\left(\\bar U^{2}\\bar A\\right)_{\\mathrm{ar}}}{\\Lambda}, \\qquad \\Lambda = \\frac{L_{\\mathrm{ar}} + L_{\\mathrm{ab}}}{2},</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.6400100000000002em;"></span><span class="strut bottom" style="height:2.32601em;vertical-align:-0.686em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathrm">Δ</span><span class="mord"><span class="mord mathit">Q</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05724em;">j</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">Δ</span><span class="mord mathit">t</span><span class="mord mspace thinspace"></span><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">σ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05724em;">j</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mspace thinspace"></span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">Λ</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.79001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="minner"><span class="minner textstyle uncramped"><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit" style="margin-right:0.10903em;">U</span></span><span style="top:-0.25233em;margin-left:0.05556em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit">A</span></span><span style="top:-0.25233em;margin-left:0.27778em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">)</span></span></span><span class="vlist"><span style="top:0.40001em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">b</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="minner"><span class="minner textstyle uncramped"><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit" style="margin-right:0.10903em;">U</span></span><span style="top:-0.25233em;margin-left:0.05556em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit">A</span></span><span style="top:-0.25233em;margin-left:0.27778em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">)</span></span></span><span class="vlist"><span style="top:0.40001em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">r</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mpunct">,</span><span class="mord mspace qquad"></span><span class="mord mathrm">Λ</span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">r</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">b</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mpunct">,</span></span></span></span></span></p><p>con <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>σ</mi><mi>j</mi></msub></mrow><annotation encoding="application/x-tex">\\sigma_j</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.716668em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">σ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05724em;">j</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span> un factor de amortiguación de la forma de Froude; la corrección se anula cuando los dos conductos no transportan caudal en el mismo sentido a través del nodo. Los pares en silla (ambos conductos hacia el nodo) o en cresta (ambos desde el nodo) reciben el tratamiento de continuidad de almacenamiento cero pero no el acoplamiento direccional de momentum. La pareja siempre se resuelve junta (no se congela por el bypass de convergencia) y se agrega una verificación de Courant a nivel de par.</p><p>La guía de uso: las uniones virtuales están pensadas para quiebres de pendiente de pequeña deflexión; los cambios de alineación horizontal deben seguir siendo cámaras de unión ordinarias con coeficientes de pérdida.</p>',12)])])}const z=a(p,[["render",m]]);export{u as __pageData,z as default};
